import{_ as r,o as a,c as o,a2 as e}from"./chunks/framework.BZO4qERu.js";const c=JSON.parse('{"title":"特效概述","description":"","frontmatter":{},"headers":[],"relativePath":"guide/effects.md","filePath":"guide/effects.md","lastUpdated":1786200137000}'),n={name:"guide/effects.md"};function s(l,t,i,d,h,g){return a(),o("div",null,[...t[0]||(t[0]=[e('<h1 id="特效概述" tabindex="-1">特效概述 <a class="header-anchor" href="#特效概述" aria-label="Permalink to &quot;特效概述&quot;">​</a></h1><p>简称<strong>特效</strong>。寄存在技能中，一个技能由数个特效构成，特效承载技能的实际效果。</p><p>特效可以改变角色的属性、能力值，或对角色施加各种状态。</p><h2 id="状态分类" tabindex="-1">状态分类 <a class="header-anchor" href="#状态分类" aria-label="Permalink to &quot;状态分类&quot;">​</a></h2><table tabindex="0"><thead><tr><th>类型</th><th>说明</th></tr></thead><tbody><tr><td><strong>增益状态</strong></td><td>提高角色能力值和属性，施加有利机制</td></tr><tr><td><strong>负面状态</strong></td><td>削减角色能力值和属性，施加有害机制（含控制效果）</td></tr></tbody></table><h2 id="控制效果" tabindex="-1">控制效果 <a class="header-anchor" href="#控制效果" aria-label="Permalink to &quot;控制效果&quot;">​</a></h2><table tabindex="0"><thead><tr><th>级别</th><th>说明</th></tr></thead><tbody><tr><td><strong>强控制效果</strong></td><td>改变角色状态，如眩晕(→完全行动不能)、封技(→技能受限)</td></tr><tr><td><strong>软控制效果</strong></td><td>不改变角色状态，但施加负面状态削减能力值，如时间减速(→减少行动速度)</td></tr></tbody></table><hr><h2 id="常见特效状态" tabindex="-1">常见特效状态 <a class="header-anchor" href="#常见特效状态" aria-label="Permalink to &quot;常见特效状态&quot;">​</a></h2><p>任何特效状态都有自己的解释权——只要在行动顺序表的框架内、规则书也尚未明确禁止的解释，都可以被接受。</p><p>特效状态需要和<strong>角色状态</strong>进行区分：如果这些特效状态没有明确改变角色状态，那么就不会对行动顺序表造成影响。</p><h3 id="生命流失" tabindex="-1">生命流失 <a class="header-anchor" href="#生命流失" aria-label="Permalink to &quot;生命流失&quot;">​</a></h3><p>生命流失是一种<strong>负面状态</strong>，使角色在时间流逝时<strong>直接减少生命值</strong>。</p><ul><li>这不是伤害，所以它<strong>不能被免疫</strong></li><li>如果角色因为生命流失死亡，那么生命流失状态的<strong>施加者</strong>就会被认定为杀人凶手</li></ul><h3 id="不可选中" tabindex="-1">不可选中 <a class="header-anchor" href="#不可选中" aria-label="Permalink to &quot;不可选中&quot;">​</a></h3><p>不可选中是一种<strong>增益状态</strong>，使角色<strong>无法被任何技能</strong>（战技、魔法、爆发技）选中（自释放除外）。</p><ul><li>在战棋地图中，角色还可以免受<strong>场地伤害</strong></li><li>角色身上现存的特效状态仍然会发挥它们的作用</li><li>角色<strong>不能</strong>免疫特效造成的伤害</li></ul><blockquote><p>这和部分免疫状态的&quot;无法被选中&quot;类似，可以说这些免疫状态也是一种不可选中。</p></blockquote><h3 id="无敌的" tabindex="-1">无敌的 <a class="header-anchor" href="#无敌的" aria-label="Permalink to &quot;无敌的&quot;">​</a></h3><p>无敌是一种<strong>增益状态</strong>：</p><ul><li>包含上述的<strong>不可选中</strong>状态</li><li><strong>免疫所有伤害</strong></li><li><strong>移除</strong>角色身上所有的特效状态——这不是驱散，这是最高级别的移除，<strong>不会考虑特效是否是不可驱散</strong></li></ul><h3 id="无敌护甲" tabindex="-1">无敌护甲 <a class="header-anchor" href="#无敌护甲" aria-label="Permalink to &quot;无敌护甲&quot;">​</a></h3><p>无敌护甲是一种<strong>增益状态</strong>：</p><ul><li>包含上述的<strong>不可选中</strong>状态</li><li><strong>免疫所有伤害</strong>，并<strong>抵抗生命流失</strong></li><li>区别于&quot;无敌&quot;：它<strong>不会移除</strong>角色的特效状态，特效状态会正常流逝、衰减持续时间以及豁免</li></ul><h3 id="中立的" tabindex="-1">中立的 <a class="header-anchor" href="#中立的" aria-label="Permalink to &quot;中立的&quot;">​</a></h3><p>中立是一种<strong>增益状态</strong>，使角色<strong>不主动参与</strong>到任何战斗中，即使该角色处于战场。</p><ul><li>如果任何角色试图攻击中立状态下的角色，都会被中立角色认定为<strong>敌人</strong>，列入反击目标</li><li>只要这些角色逃离中立角色的攻击范围，经过一段时间后，中立角色就会解除对这些角色的敌人认定</li></ul>',27)])])}const p=r(n,[["render",s]]);export{c as __pageData,p as default};
